export const dynamic = "force-dynamic";
const ABAS: [string, string][] = [["resumo", "Resumo"], ["cadastro", "Cadastro"], ["homologacao", "Homologação"], ["documentos", "Documentos"], ["financeiro", "Financeiro e banco"], ["desempenho", "Desempenho"], ["transacoes", "Contratos e títulos"], ["portal", "Portal"], ["historico", "Histórico"]];
