  const caso = casos.find(c => ["ANALISE", "APROVACAO"].includes(c.fase)) ?? null; const rvCaso = caso ? reviews.filter(r => r.homologation_id === caso.id) : [];
  const exigidos = caso ? F.pareceresExigidos(caso.criticidade) : F.pareceresExigidos(l.criticidade);
  const emUso = contas.find(c => c.status === "EM_USO") ?? null; const mAberta = mudancas.find(m => ["AGUARDANDO_CONFERENCIA", "AGUARDANDO_APROVACAO"].includes(m.status)) ?? null; const proposta = mAberta ? contas.find(c => c.id === mAberta.account_id) ?? null : null;
  const revelar = F.podeVerBancoCompleto(s) && F.revelarValido(sp.rev, s.id, id); const risco = F.riscoExibido(l); const ultima = avals[0] ?? null;
  const ch12 = chamados.filter(c => c.created_at >= addDays(h, -365)); const chConc = ch12.filter(c => c.status === "CONCLUIDO"); const chPrazo = chConc.filter(c => !c.sla_ate || (c.concluido_em && c.concluido_em <= c.sla_ate)); const chAval = ch12.filter(c => c.avaliacao !== null);
  const fmtDoc = (tipo: string, d: string) => F.fmtDocumento(tipo, d, revelar);
